import {
  motion,
  type MotionValue,
  type Transition,
  useReducedMotion,
  useSpring,
  useTransform,
  useVelocity,
} from 'motion/react';

import { TaskCardBody } from './card-parts';
import type { Task } from './data';

const VELOCITY_RANGE = [-1400, 0, 1400];

const TILT_RANGE = [-5, 0, 5];

const TILT_SPRING = { stiffness: 380, damping: 26, mass: 0.6 };

const LIFT: Transition = { type: 'spring', bounce: 0, duration: 0.25 };

const INSTANT: Transition = { duration: 0 };

function liftOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LIFT;
}

function liftScaleOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 1;
  }
  return 1.02;
}

type OverlayCardProps = {
  task: Task;
  dragX: MotionValue<number>;
};

/** The card under the pointer: it leans with the speed of the drag and settles on a spring when the pointer slows. */
export function OverlayCard({ task, dragX }: OverlayCardProps) {
  const shouldReduceMotion = useReducedMotion();
  const velocity = useVelocity(dragX);
  const tiltTarget = useTransform(velocity, VELOCITY_RANGE, TILT_RANGE, {
    clamp: true,
  });
  const tilt = useSpring(tiltTarget, TILT_SPRING);
  const noTilt = useTransform(tilt, () => 0);
  let rotate = tilt;
  if (shouldReduceMotion) {
    rotate = noTilt;
  }

  return (
    <motion.div
      style={{ rotate }}
      initial={{ scale: 1 }}
      animate={{ scale: liftScaleOf(shouldReduceMotion) }}
      transition={liftOf(shouldReduceMotion)}
      className='surface-raised cursor-grabbing rounded-lg'
    >
      <TaskCardBody task={task} />
    </motion.div>
  );
}

import {
  closestCenter,
  closestCorners,
  pointerWithin,
  type Active,
  type CollisionDetection,
  type Over,
} from '@dnd-kit/core';
import { arrayMove } from '@dnd-kit/sortable';

import type { Columns, LaneId } from './data';

const HIDDEN_PREFIX = 'hidden:';

export function isLaneId(columns: Columns, id: string): id is LaneId {
  return Object.prototype.hasOwnProperty.call(columns, id);
}

export function hiddenDropIdOf(laneId: LaneId) {
  return `${HIDDEN_PREFIX}${laneId}`;
}

/** The lane behind a row of the hidden columns list, or null for any other droppable. */
export function hiddenLaneOf(columns: Columns, id: string): LaneId | null {
  if (!id.startsWith(HIDDEN_PREFIX)) {
    return null;
  }
  const laneId = id.slice(HIDDEN_PREFIX.length);
  if (isLaneId(columns, laneId)) {
    return laneId;
  }
  return null;
}

/** Drops the card at the end of a lane that is folded into the hidden columns list. */
export function moveToLaneEnd(
  columns: Columns,
  taskId: string,
  laneId: LaneId
): Columns {
  const fromLane = laneOf(columns, taskId);
  if (!fromLane) {
    return columns;
  }
  if (fromLane === laneId) {
    return columns;
  }
  const fromItems = columns[fromLane].filter((id) => id !== taskId);
  const toItems = [...columns[laneId], taskId];
  return { ...columns, [fromLane]: fromItems, [laneId]: toItems };
}

export function laneOf(columns: Columns, taskId: string): LaneId | null {
  const lanes = Object.keys(columns) as LaneId[];
  const lane = lanes.find((laneId) => columns[laneId].includes(taskId));
  if (lane) {
    return lane;
  }
  return null;
}

export function targetLaneOf(columns: Columns, overId: string) {
  if (isLaneId(columns, overId)) {
    return overId;
  }
  return laneOf(columns, overId);
}

/** Inside the lane under the pointer, the closest card wins; an empty lane is the target itself. */
export function detectBoardCollision(
  args: Parameters<CollisionDetection>[0],
  columns: Columns
) {
  const hasPointer = Boolean(args.pointerCoordinates);
  if (!hasPointer) {
    return closestCorners(args);
  }
  const pointerHits = pointerWithin(args);
  const hiddenHit = pointerHits.find((hit) =>
    String(hit.id).startsWith(HIDDEN_PREFIX)
  );
  if (hiddenHit) {
    return [hiddenHit];
  }
  const laneHit = pointerHits.find((hit) => isLaneId(columns, String(hit.id)));
  if (!laneHit) {
    return pointerHits;
  }
  const laneTaskIds = columns[laneHit.id as LaneId];
  const cardContainers = args.droppableContainers.filter((container) =>
    laneTaskIds.includes(String(container.id))
  );
  const isEmptyLane = cardContainers.length === 0;
  if (isEmptyLane) {
    return [laneHit];
  }
  return closestCenter({ ...args, droppableContainers: cardContainers });
}

function isBelowOver(active: Active, over: Over) {
  const translated = active.rect.current.translated;
  if (!translated) {
    return false;
  }
  const overMiddle = over.rect.top + over.rect.height / 2;
  return translated.top > overMiddle;
}

/** Moves the dragged card into the lane under it, before or after the card it hovers. */
export function moveAcrossLanes(
  columns: Columns,
  active: Active,
  over: Over
): Columns {
  const activeId = String(active.id);
  const overId = String(over.id);
  const fromLane = laneOf(columns, activeId);
  const toLane = targetLaneOf(columns, overId);
  if (!fromLane) {
    return columns;
  }
  if (!toLane) {
    return columns;
  }
  if (fromLane === toLane) {
    return columns;
  }
  const fromItems = columns[fromLane].filter((id) => id !== activeId);
  const toItems = columns[toLane];
  let insertAt = toItems.length;
  const isOverCard = !isLaneId(columns, overId);
  if (isOverCard) {
    const overIndex = toItems.indexOf(overId);
    insertAt = overIndex;
    if (isBelowOver(active, over)) {
      insertAt = overIndex + 1;
    }
  }
  const nextToItems = [
    ...toItems.slice(0, insertAt),
    activeId,
    ...toItems.slice(insertAt),
  ];
  return { ...columns, [fromLane]: fromItems, [toLane]: nextToItems };
}

/** Reorders the dragged card inside its lane once it is dropped. */
export function reorderInLane(
  columns: Columns,
  activeId: string,
  overId: string
): Columns {
  const lane = laneOf(columns, activeId);
  if (!lane) {
    return columns;
  }
  const items = columns[lane];
  const oldIndex = items.indexOf(activeId);
  const newIndex = items.indexOf(overId);
  const isMissing = newIndex === -1;
  const isSamePlace = oldIndex === newIndex;
  if (isMissing || isSamePlace) {
    return columns;
  }
  return { ...columns, [lane]: arrayMove(items, oldIndex, newIndex) };
}

import type { LabelId, Priority, Task } from './data';

export type Filters = {
  priorities: Priority[];
  assigneeIds: string[];
  labels: LabelId[];
};

export const NO_FILTERS: Filters = {
  priorities: [],
  assigneeIds: [],
  labels: [],
};

export function activeFilterCountOf(filters: Filters) {
  const priorityCount = filters.priorities.length;
  const assigneeCount = filters.assigneeIds.length;
  const labelCount = filters.labels.length;
  return priorityCount + assigneeCount + labelCount;
}

function matchesPriority(task: Task, filters: Filters) {
  const isUnfiltered = filters.priorities.length === 0;
  if (isUnfiltered) {
    return true;
  }
  return filters.priorities.includes(task.priority);
}

function matchesAssignee(task: Task, filters: Filters) {
  const isUnfiltered = filters.assigneeIds.length === 0;
  if (isUnfiltered) {
    return true;
  }
  return task.assigneeIds.some((personId) =>
    filters.assigneeIds.includes(personId)
  );
}

function matchesLabel(task: Task, filters: Filters) {
  const isUnfiltered = filters.labels.length === 0;
  if (isUnfiltered) {
    return true;
  }
  return task.labels.some((labelId) => filters.labels.includes(labelId));
}

/** Values of one property combine with "or", properties combine with "and". */
export function matchesFilters(task: Task, filters: Filters) {
  const hasPriority = matchesPriority(task, filters);
  const hasAssignee = matchesAssignee(task, filters);
  const hasLabel = matchesLabel(task, filters);
  return hasPriority && hasAssignee && hasLabel;
}

export function toggledValue<Value>(values: Value[], value: Value) {
  const isPicked = values.includes(value);
  if (isPicked) {
    return values.filter((candidate) => candidate !== value);
  }
  return [...values, value];
}

