import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

const PILL_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PILL_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

const PILL_PRESENCE: Variants = {
  hidden: { opacity: 0, y: 8, scale: 0.97, transition: PILL_OUT },
  shown: { opacity: 1, y: 0, scale: 1, transition: PILL_IN },
};

const PILL_FADE: Variants = {
  hidden: { opacity: 0, transition: PILL_OUT },
  shown: { opacity: 1, transition: PILL_IN },
};

function pillVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return PILL_FADE;
  }
  return PILL_PRESENCE;
}

function hiddenLabelOf(count: number) {
  if (count === 1) {
    return 'task hidden by filters';
  }
  return 'tasks hidden by filters';
}

type FilterPillProps = {
  hiddenCount: number;
  onClear: () => void;
};

/** Floats over the board while filters hide tasks, so the board itself never moves. */
export function FilterPill({ hiddenCount, onClear }: FilterPillProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = pillVariantsOf(shouldReduceMotion);
  const isVisible = hiddenCount > 0;
  const hiddenLabel = hiddenLabelOf(hiddenCount);

  return (
    <div className='pointer-events-none absolute inset-x-0 bottom-4 z-10 flex justify-center px-4'>
      <AnimatePresence initial={false}>
        {isVisible && (
          <motion.div
            key='filter-pill'
            role='status'
            variants={variants}
            initial='hidden'
            animate='shown'
            exit='hidden'
            className='surface-raised pointer-events-auto flex h-10 items-center gap-3 rounded-full pr-1.5 pl-4 text-[13px]'
          >
            <span className='flex items-center gap-1'>
              <MotionNumber value={hiddenCount} className='font-medium' />
              <WordRoll
                text={hiddenLabel}
                value={hiddenCount}
                className='text-muted-foreground'
              />
            </span>
            <Button variant='secondary' size='sm' onClick={onClear}>
              <XIcon />
              Clear filters
            </Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';

import { EyeIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { LaneTile, type LaneMeta } from './board-lane';
import { hiddenDropIdOf } from './board-moves';
import type { LaneId } from './data';

type HiddenLaneRowProps = {
  lane: LaneMeta;
  count: number;
  isTarget: boolean;
  onShow: (laneId: LaneId) => void;
};

function HiddenLaneRow({ lane, count, isTarget, onShow }: HiddenLaneRowProps) {
  const { setNodeRef } = useDroppable({ id: hiddenDropIdOf(lane.id) });

  function showLane() {
    onShow(lane.id);
  }

  return (
    <li
      ref={setNodeRef}
      className={cn(
        'flex h-10 items-center gap-2 rounded-lg pr-1 pl-2.5 transition-colors duration-150',
        isTarget && 'bg-primary/[0.08]'
      )}
    >
      <LaneTile lane={lane} />
      <span className='min-w-0 flex-1 truncate text-[13px] font-medium'>
        {lane.label}
      </span>
      <span className='text-muted-foreground text-xs tabular-nums'>
        {count}
      </span>
      <Button
        variant='ghost'
        size='icon-sm'
        aria-label={`Show the ${lane.label} column`}
        onClick={showLane}
        className='text-muted-foreground'
      >
        <EyeIcon />
      </Button>
    </li>
  );
}

type HiddenColumnsProps = {
  lanes: LaneMeta[];
  countOf: (laneId: LaneId) => number;
  targetLaneId: LaneId | null;
  onShow: (laneId: LaneId) => void;
};

/** Folded lanes gather at the end of the board. Each row still takes a dropped card. */
export function HiddenColumns({
  lanes,
  countOf,
  targetLaneId,
  onShow,
}: HiddenColumnsProps) {
  return (
    <section
      aria-label='Hidden columns'
      className='bg-foreground/[0.03] flex w-60 shrink-0 snap-start flex-col rounded-xl'
    >
      <header className='flex h-11 items-center px-3'>
        <h2 className='text-muted-foreground text-[13px] font-semibold'>
          Hidden columns
        </h2>
      </header>
      <ul className='flex flex-col gap-0.5 px-1.5 pb-1.5'>
        {lanes.map((lane) => (
          <HiddenLaneRow
            key={lane.id}
            lane={lane}
            count={countOf(lane.id)}
            isTarget={targetLaneId === lane.id}
            onShow={onShow}
          />
        ))}
      </ul>
    </section>
  );
}

